updateThreadView() {
  switch (Services.prefs.getIntPref("mail.threadpane.listview", 0)) {
    case 1:
      // Table view.
      threadTree.setAttribute("rows", "thread-row");
      threadTree.headerHidden = false;
      break;
    case 0:
    default:
      // Cards view.
      threadTree.setAttribute("rows", "thread-card");
      threadTree.headerHidden = true;
      break;
  }
},
